verify.command:
py="$HOME/.cairn/venv/Scripts/python.exe"; ps() { powershell.exe -NoProfile -Command "$1" </dev/null | tr -d '\r'; }
on32=$(ps "Get-NetTCPConnection -LocalPort 5432 -State Listen -ErrorAction SilentlyContinue | ForEach-Object { (Get-Process -Id \$_.OwningProcess).Name } | Sort-Object -Unique")
printf %s "$on32" | grep -qi postgres && { echo 'RED: PostgreSQL is bound to 5432, the local db proxy address on a non-home box; move it to 5433'; exit 1; }
addrs=$(ps "Get-NetTCPConnection -LocalPort 5433 -State Listen -ErrorAction SilentlyContinue | ForEach-Object { \$_.LocalAddress } | Sort-Object -Unique")
[ -n "$addrs" ] || { echo 'RED: nothing listens on 5433'; exit 1; }
wide=$(printf '%s\n' $addrs | grep -v -x -e '127.0.0.1' -e '::1'); [ -z "$wide" ] || { echo "RED: 5433 listens beyond loopback on: $(echo $wide)"; exit 1; }
svc=$(sc.exe query type= service state= all | sed -n 's/^SERVICE_NAME: \(postgresql-x64-[0-9]*\).*/\1/p' | head -1); [ -n "$svc" ] || { echo 'RED: something listens on 5433 but no postgresql-x64-* service is installed'; exit 1; }
sc.exe query "$svc" | grep -q RUNNING || { echo "RED: service $svc is not RUNNING"; exit 1; }
sc.exe qc "$svc" | grep -q AUTO_START || { echo "RED: service $svc does not start automatically"; exit 1; }
pg="$HOME/.cairn/devices/db_domain/0/pgpass"; [ -s "$pg" ] || { echo 'RED: no pgpass at ~/.cairn/devices/db_domain/0/pgpass'; exit 1; }
grep -q '^127.0.0.1:5432:' "$pg" && { echo 'RED: pgpass still names 5432 (the proxy address)'; exit 1; }
out=$("$py" -I -c 'import os,pathlib,psycopg2; p=pathlib.Path.home()/".cairn/devices/db_domain/0/pgpass"; c=psycopg2.connect(host="127.0.0.1",port=5433,dbname="cairn",user=os.environ["USERNAME"],passfile=str(p)); cur=c.cursor(); cur.execute("select current_user"); print(cur.fetchone()[0]); c.close()' </dev/null 2>&1) || { echo "RED: connect to cairn on 127.0.0.1:5433 failed: $(printf %s "$out" | tail -1)"; exit 1; }
echo "green: $svc running and automatic on loopback 5433, nothing of it on 5432, pgpass present, cairn reached as $out"
